def find_order(orders, wanted_id):
    for order in orders:
        if order["cancelled"]:
            continue
        if order["id"] == wanted_id:
            print("found", order)
            break
    else:
        print("active order not found")

orders = [
    {"id": 1, "cancelled": True},
    {"id": 2, "cancelled": False},
]
find_order(orders, 2)  # found ...; else is skipped
find_order(orders, 3)  # active order not found
